const DB='mahdyar_db', STORE='data'; let db, items=[], loans=[], letters=[], editingId=null;
let cloud=null, cloudChannel=null, applyingRemote=false;
function cloudConfigured(){return !!(window.MAHDYAR_SUPABASE_URL&&window.MAHDYAR_SUPABASE_ANON_KEY&&!window.MAHDYAR_SUPABASE_URL.includes('YOUR-PROJECT')&&!window.MAHDYAR_SUPABASE_ANON_KEY.includes('YOUR_'));}
if(cloudConfigured()&&window.supabase?.createClient){cloud=window.supabase.createClient(window.MAHDYAR_SUPABASE_URL,window.MAHDYAR_SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}})}
function showApp(){ $('loginScreen').classList.add('hidden'); $('appShell').classList.remove('hidden'); if(window.lucide)lucide.createIcons(); updateTehranClock(); }
async function login(){let u=$('loginUser').value.trim(),pw=$('loginPass').value,email=window.MAHDYAR_AUTH_EMAIL||'';if(u!=='تبلیغات'||!pw){$('loginError').textContent='نام کاربری یا رمز عبور را بررسی کن.';return}if(!cloud){$('loginError').textContent='تنظیمات اتصال پایگاه داده کامل نیست؛ فایل cloud-config.js را بررسی کن.';return}if(!email||email.includes('ایمیل-حساب')||email.includes('YOUR-EMAIL')){$('loginError').textContent='ایمیل حساب مشترک هنوز در فایل cloud-config.js وارد نشده است.';return}let {error}=await cloud.auth.signInWithPassword({email,password:pw});if(error){$('loginError').textContent='ورود انجام نشد؛ رمز یا تنظیمات حساب را بررسی کن.';return}$('loginPass').value='';try{await readAll();await startCloudSync();showApp();$('letterDate').value=jalaliToday();$('reportMonth').value=jalaliMonthToday();renderAll();checkDue()}catch(e){$('loginError').textContent='ورود انجام شد، اما دریافت اطلاعات انبار ناموفق بود. اتصال و دسترسی جدول را بررسی کن.';console.error(e)}}
async function logout(){if(cloud)await cloud.auth.signOut();if(cloudChannel){await cloud.removeChannel(cloudChannel);cloudChannel=null}location.reload()}
function logoutAllNotice(){alert('برای قطع دسترسی همه گوشی‌ها، در پنل Supabase نشست‌های حساب را لغو کن و رمز حساب مشترک را تغییر بده.');}
async function startCloudSync(){if(!cloud)return;if(cloudChannel)await cloud.removeChannel(cloudChannel);cloudChannel=cloud.channel('mahdyar-inventory-live').on('postgres_changes',{event:'*',schema:'public',table:'inventory_state',filter:'id=eq.1'},async payload=>{if(applyingRemote)return;let d=payload.new?.data;if(!d)return;applyingRemote=true;try{items=d.items||[];loans=d.loans||[];letters=d.letters||[];await writeLocal();renderAll()}finally{applyingRemote=false}}).subscribe((status)=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')console.warn('Supabase Realtime connection:',status)});}

const $=id=>document.getElementById(id);
const fa=n=>Number(n||0).toLocaleString('fa-IR');
function today(){let p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),o={};p.forEach(x=>o[x.type]=x.value);return `${o.year}-${o.month}-${o.day}`}
function faNum(v){return String(v).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[+d]);}
function jalaliParts(iso){let d=new Date(iso+'T12:00:00Z'),p=new Intl.DateTimeFormat('en-u-ca-persian',{timeZone:'UTC',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(d),o={};p.forEach(x=>o[x.type]=x.value);return {y:Number(o.year),m:Number(o.month),d:Number(o.day)}}
function jalaliToday(){return faDate(today())}
function updateTehranClock(){let el=$('tehranClock');if(el)el.textContent=new Intl.DateTimeFormat('fa-IR-u-ca-persian',{dateStyle:'full',timeStyle:'short',timeZone:'Asia/Tehran'}).format(new Date())}
function jalaliMonthToday(){let p=jalaliParts(today());return `${faNum(p.y)}/${faNum(String(p.m).padStart(2,'0'))}`}
function parseJalali(v){if(!v)return '';let z=String(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[.-]/g,'/').trim(),m=z.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);if(!m)return '';let [_,yy,mm,dd]=m.map(Number);if(mm<1||mm>12||dd<1||dd>31)return '';let start=Date.UTC(yy+621,0,1);for(let i=0;i<380;i++){let dt=new Date(start+i*86400000),p=new Intl.DateTimeFormat('en-u-ca-persian',{timeZone:'UTC',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(dt),o={};p.forEach(x=>o[x.type]=x.value);if(+o.year===yy&&+o.month===mm&&+o.day===dd)return dt.toISOString().slice(0,10)}return '';}
function getJDate(id){let v=$(id).value.trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;return parseJalali(v)}
function setJDate(id,iso){$(id).value=iso?faDate(iso):''}
function getJMonth(){let v=$('reportMonth').value.trim().replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)),m=v.match(/^(\d{4})[\/.-](\d{1,2})$/);if(!m)return today().slice(0,7);let iso=parseJalali(`${m[1]}/${m[2]}/01`);return iso?iso.slice(0,7):today().slice(0,7)}
function setJMonth(iso){let p=jalaliParts(iso+'-01');$('reportMonth').value=`${faNum(p.y)}/${faNum(String(p.m).padStart(2,'0'))}`}

function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>reject(r.error)})}
function writeLocal(){return new Promise(resolve=>{let t=db.transaction(STORE,'readwrite');t.objectStore(STORE).put({items,loans,letters},'app');t.oncomplete=resolve})}
async function readAll(){let t=db.transaction(STORE,'readonly').objectStore(STORE).get('app');await new Promise((resolve,reject)=>{t.onsuccess=()=>{let d=t.result||{};items=d.items||[];loans=d.loans||[];letters=d.letters||[];resolve()};t.onerror=()=>reject(t.error)});if(!cloud)return;let {data,error}=await cloud.from('inventory_state').select('data').eq('id',1).maybeSingle();if(error)throw error;if(data?.data){items=data.data.items||[];loans=data.data.loans||[];letters=data.data.letters||[];await writeLocal();return}let initial={items,loans,letters};let result=await cloud.from('inventory_state').upsert({id:1,data:initial,updated_at:new Date().toISOString()},{onConflict:'id'});if(result.error)throw result.error}
async function persist(){await writeLocal();if(cloud&&!applyingRemote){let {error}=await cloud.from('inventory_state').upsert({id:1,data:{items,loans,letters},updated_at:new Date().toISOString()},{onConflict:'id'});if(error){console.error('Cloud sync failed',error);alert('اطلاعات روی همین گوشی ذخیره شد، اما همگام‌سازی با سرور انجام نشد. اینترنت و دسترسی Supabase را بررسی کن.')}}}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function showPage(p){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(p).classList.add('active');document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===p));if(p==='reports')renderReport();if(p==='letters')renderLetters();if(p==='home')renderHome();window.scrollTo(0,0)}
function available(item){return Math.max(0,Number(item.qty)-loans.filter(l=>l.itemId===item.id&&!l.returned).reduce((s,l)=>s+Number(l.qty),0))}
function newItem(){editingId=null;$('itemFormTitle').textContent='ثبت وسیله جدید';['iName','iPlace','iNote'].forEach(x=>$(x).value='');$('iQty').value=1;$('iCategory').value='کتیبه';$('iPhoto').value='';$('itemForm').classList.remove('hidden')}
function cancelItem(){$('itemForm').classList.add('hidden')}
async function fileData(file){if(!file)return null;return await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
async function saveItem(){let name=$('iName').value.trim(),qty=Number($('iQty').value);if(!name||qty<1)return alert('نام وسیله و تعداد معتبر را وارد کن.');let old=items.find(x=>x.id===editingId),photo=await fileData($('iPhoto').files[0]);let obj={id:editingId||uid(),name,category:$('iCategory').value,qty,place:$('iPlace').value,note:$('iNote').value,photo:photo||old?.photo||null,created:old?.created||today()};if(old)items=items.map(x=>x.id===old.id?obj:x);else items.unshift(obj);await persist();cancelItem();renderItems();renderHome()}
function editItem(id){let x=items.find(i=>i.id===id);if(!x)return;editingId=id;$('itemFormTitle').textContent='ویرایش وسیله';$('iName').value=x.name;$('iCategory').value=x.category;$('iQty').value=x.qty;$('iPlace').value=x.place||'';$('iNote').value=x.note||'';$('iPhoto').value='';$('itemForm').classList.remove('hidden');window.scrollTo(0,0)}
async function deleteItem(id){if(loans.some(l=>l.itemId===id&&!l.returned))return alert('این وسیله امانت فعال دارد؛ ابتدا بازگشت آن را ثبت کن.');if(confirm('این وسیله حذف شود؟')){items=items.filter(x=>x.id!==id);await persist();renderItems();renderHome()}}
function renderItems(){let q=($('itemSearch')?.value||'').trim().toLowerCase(),list=items.filter(x=>(x.name+' '+x.category).toLowerCase().includes(q));$('itemsList').innerHTML=list.length?list.map(x=>`<div class="item"><img class="thumb" src="${x.photo||'icon.png'}"><div class="grow"><strong>${esc(x.name)}</strong><div class="muted">${esc(x.category)} · کل ${fa(x.qty)} · موجود ${fa(available(x))}</div><div class="muted">${esc(x.place||'محل نگهداری ثبت نشده')}</div></div><div><button class="small secondary" onclick="editItem('${x.id}')">ویرایش</button> <button class="small danger" onclick="deleteItem('${x.id}')">حذف</button></div></div>`).join(''):'<div class="empty">هنوز وسیله‌ای ثبت نشده است.</div>'}
function openLoanForm(){if(!items.length)return alert('ابتدا یک وسیله در بخش موجودی ثبت کن.');$('lItem').innerHTML=items.map(x=>`<option value="${x.id}">${esc(x.name)} (موجود: ${fa(available(x))})</option>`).join('');setJDate('lOut',today());setJDate('lDue',today());$('lPerson').value='';$('lPhone').value='';$('lQty').value=1;$('lNote').value='';$('loanForm').classList.remove('hidden')}
function closeLoanForm(){$('loanForm').classList.add('hidden')}
async function saveLoan(){let item=items.find(x=>x.id===$('lItem').value),qty=Number($('lQty').value),person=$('lPerson').value.trim(),out=getJDate('lOut'),due=getJDate('lDue');if(!item||!person||qty<1)return alert('وسیله، نام امانت‌گیرنده و تعداد را کامل کن.');if(qty>available(item))return alert('تعداد واردشده از موجودی فعلی بیشتر است.');if(due&&out&&due<out)return alert('موعد بازگشت نمی‌تواند قبل از تاریخ تحویل باشد.');loans.unshift({id:uid(),itemId:item.id,itemName:item.name,qty,person,phone:$('lPhone').value,out,due,note:$('lNote').value,returned:false,created:today(),notified:false});await persist();closeLoanForm();renderLoans();renderItems();renderHome();checkDue(true)}
async function returnLoan(id){let l=loans.find(x=>x.id===id);if(l&&confirm('بازگشت این امانت ثبت شود؟')){l.returned=true;l.returnDate=today();await persist();renderLoans();renderItems();renderHome()}}
async function deleteLoan(id){if(confirm('این سابقه امانت حذف شود؟')){loans=loans.filter(x=>x.id!==id);await persist();renderLoans();renderHome()}}
function renderLoans(){let active=loans.filter(x=>!x.returned);$('loansList').innerHTML=loans.length?loans.map(l=>{let late=!l.returned&&l.due&&l.due<today();return `<div class="item"><div class="grow"><strong>${esc(l.itemName)} · ${fa(l.qty)} عدد</strong><div class="muted">تحویل‌گیرنده: ${esc(l.person)} ${l.phone?'· '+esc(l.phone):''}</div><div class="muted">تحویل: ${faDate(l.out)} · موعد: ${faDate(l.due)}</div><span class="pill ${l.returned?'green':late?'red':''}">${l.returned?'بازگشت ثبت شده':late?'دیرکرد':'نزد امانت‌گیرنده'}</span></div><div>${!l.returned?`<button class="small" onclick="returnLoan('${l.id}')">ثبت بازگشت</button>`:''}<button class="small danger" onclick="deleteLoan('${l.id}')">حذف</button></div></div>`}).join(''):'<div class="empty">هنوز امانتی ثبت نشده است.</div>'}
function faDate(v){if(!v)return'—';let p=jalaliParts(v);return `${faNum(p.y)}/${faNum(String(p.m).padStart(2,'0'))}/${faNum(String(p.d).padStart(2,'0'))}`}
function renderHome(){let total=items.reduce((s,x)=>s+Number(x.qty),0),loaned=loans.filter(x=>!x.returned).reduce((s,x)=>s+Number(x.qty),0),over=loans.filter(x=>!x.returned&&x.due&&x.due<today());$('sTotal').textContent=fa(total);$('sAvailable').textContent=fa(total-loaned);$('sLoaned').textContent=fa(loaned);$('sOverdue').textContent=fa(over.reduce((s,x)=>s+Number(x.qty),0));$('dueBox').classList.toggle('hidden',!over.length);$('dueBox').textContent=over.length?'یادآوری: '+over.map(x=>`${x.itemName} نزد ${x.person}`).join('، ')+' موعد بازگشتش گذشته است.':'';$('recentLoans').innerHTML=loans.slice(0,4).map(l=>`<div style="padding:7px 0;border-bottom:1px solid var(--line)">${esc(l.itemName)} — ${esc(l.person)} — ${l.returned?'بازگشت شده':'امانت فعال'}</div>`).join('')||'هنوز امانتی ثبت نشده است.'}
function renderReport(){let m=getJMonth();setJMonth(m);let rows=items.map(x=>({x,avail:available(x),loaned:Number(x.qty)-available(x)}));$('reportPreview').innerHTML=`<div class="muted">گزارش ماه ${faDate(m+'-01')}</div><p>تعداد اقلام: ${fa(items.length)} · تعداد کل: ${fa(rows.reduce((s,r)=>s+r.x.qty,0))} · موجود: ${fa(rows.reduce((s,r)=>s+r.avail,0))} · امانت: ${fa(rows.reduce((s,r)=>s+r.loaned,0))}</p>`+tableRows(rows)}
function tableRows(rows){return `<table><thead><tr><th>ردیف</th><th>نام وسیله</th><th>دسته</th><th>کل</th><th>موجود</th><th>امانت</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${fa(i+1)}</td><td>${esc(r.x.name)}</td><td>${esc(r.x.category)}</td><td>${fa(r.x.qty)}</td><td>${fa(r.avail)}</td><td>${fa(r.loaned)}</td></tr>`).join('')}</tbody></table>`}
function printHeader(title,sub){return `<div class="print-head"><img src="data:image/jpeg;base64,"><div class="print-title"><h1>گروه جهادی مهدیار</h1><p>سامانه مدیریت تجهیزات و فضاسازی هیئت</p><h2>${title}</h2><p>${sub||''}</p></div></div>`}
function printReport(){let m=getJMonth(),rows=items.map(x=>({x,avail:available(x),loaned:Number(x.qty)-available(x)}));let active=loans.filter(x=>!x.returned);$('printArea').innerHTML=printHeader('گزارش ماهانه موجودی',`دوره: ${faDate(m+'-01')} · تاریخ تهیه: ${faDate(today())}`)+`<div class="print-meta"><span>تعداد اقلام: ${fa(items.length)}</span><span>تعداد کل: ${fa(rows.reduce((s,r)=>s+r.x.qty,0))}</span><span>امانت فعال: ${fa(active.length)} مورد</span></div>`+tableRows(rows)+`<h3 style="margin-top:24px">امانت‌های فعال</h3><table><thead><tr><th>وسیله</th><th>تعداد</th><th>امانت‌گیرنده</th><th>تاریخ تحویل</th><th>موعد بازگشت</th><th>وضعیت</th></tr></thead><tbody>${active.map(l=>`<tr><td>${esc(l.itemName)}</td><td>${fa(l.qty)}</td><td>${esc(l.person)}</td><td>${faDate(l.out)}</td><td>${faDate(l.due)}</td><td>${l.due<today()?'دیرکرد':'امانت فعال'}</td></tr>`).join('')}</tbody></table><div class="signature"><span>تهیه‌کننده: مسئول فضاسازی و دکور</span><span>تأیید مسئول هیئت: ....................</span></div>`;$('printArea').classList.remove('hidden');window.print();$('printArea').classList.add('hidden')}
function printLetter(){let d=getJDate('letterDate')||today();$('printArea').innerHTML=printHeader('نامه اداری',`شماره: ${esc($('letterNo').value||'—')} · تاریخ: ${faDate(d)}`)+`<p>گیرنده: ${esc($('letterTo').value||'مسئول محترم هیئت')}</p><p><b>موضوع: ${esc($('letterSubject').value||'—')}</b></p><div class="letter-body">${esc($('letterBody').value||'')}</div><div class="signature"><span>با احترام<br>${esc($('letterSigner').value||'مسئول فضاسازی و دکور')}</span><span>امضا: ........................</span></div>`;$('printArea').classList.remove('hidden');window.print();$('printArea').classList.add('hidden')}
async function saveLetter(){let obj={id:uid(),no:$('letterNo').value,date:getJDate('letterDate')||today(),to:$('letterTo').value,subject:$('letterSubject').value,body:$('letterBody').value,signer:$('letterSigner').value};letters.unshift(obj);await persist();renderLetters();alert('پیش‌نویس نامه ذخیره شد.')}
function renderLetters(){$('lettersList').innerHTML=letters.length?letters.map(l=>`<div class="item"><div class="grow"><strong>${esc(l.subject||'بدون موضوع')}</strong><div class="muted">شماره ${esc(l.no||'—')} · ${faDate(l.date)}</div></div><button class="small secondary" onclick="loadLetter('${l.id}')">بازکردن</button></div>`).join(''):'<div class="empty">پیش‌نویسی ذخیره نشده است.</div>'}
function loadLetter(id){let l=letters.find(x=>x.id===id);if(!l)return;showPage('letters');$('letterNo').value=l.no;setJDate('letterDate',l.date);$('letterTo').value=l.to;$('letterSubject').value=l.subject;$('letterBody').value=l.body;$('letterSigner').value=l.signer}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function enableNotifications(){if(!('Notification'in window))return alert('این مرورگر از اعلان پشتیبانی نمی‌کند.');let p=await Notification.requestPermission();alert(p==='granted'?'اعلان‌ها فعال شد.':'مجوز اعلان داده نشد.')}
async function checkDue(force=false){let due=loans.filter(l=>!l.returned&&l.due&&l.due<=today()&&!l.notified);if(!due.length)return;let msg=due.map(l=>`${l.itemName} (${l.person})`).join('، ');if('Notification'in window&&Notification.permission==='granted'){new Notification('یادآوری امانت | مهدیار',{body:'موعد بازگشت: '+msg,icon:'icon.png'});due.forEach(l=>l.notified=true);await persist()}else if(force||due.length)console.info('موعد امانت:',msg)}
function exportBackup(){let blob=new Blob([JSON.stringify({version:1,items,loans,letters},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='پشتیبان-انبار-مهدیار-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}
async function importBackup(e){let f=e.target.files[0];if(!f)return;try{let d=JSON.parse(await f.text());if(!Array.isArray(d.items)||!Array.isArray(d.loans))throw 0;if(!confirm('اطلاعات فعلی با اطلاعات فایل پشتیبان جایگزین شود؟'))return;items=d.items;loans=d.loans;letters=d.letters||[];await persist();renderAll();alert('بازیابی انجام شد.')}catch(_){alert('فایل پشتیبان معتبر نیست.')}e.target.value=''}
function renderAll(){renderHome();renderItems();renderLoans();renderReport();renderLetters();if(window.lucide)lucide.createIcons()}
(async()=>{await openDB();if(cloud){let {data,error}=await cloud.auth.getSession();if(error)console.warn(error);if(data?.session){try{await readAll();await startCloudSync();showApp();setJDate('letterDate',today());setJMonth(today().slice(0,7));renderAll();checkDue()}catch(e){console.error(e);$('loginScreen').classList.remove('hidden');$('loginError').textContent='دریافت اطلاعات انبار ناموفق بود؛ اینترنت و تنظیمات Supabase را بررسی کن.'}}else{$('loginScreen').classList.remove('hidden')}}else{$('loginScreen').classList.remove('hidden');$('loginError').textContent='تنظیمات اتصال کامل نیست؛ فایل cloud-config.js را بررسی کن.'}})();

setInterval(updateTehranClock,30000);
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
